#!/usr/bin/env python3
"""
detect_input.py — 自动识别用户输入的数据源类型（仅文本和本地文件）。

用法：
    from detect_input import detect_data_source
    src = detect_data_source(user_input_text)
    # src = {"type": "local_file"|"local_data"|"keyword_only", "value": ...}
"""
import json
import os
import re
from typing import Dict, Optional


FILE_EXT_PATTERN = re.compile(r'([A-Za-z0-9_\-./\u4e00-\u9fa5]+?\.(?:log|xlsx|xls|json|csv|txt))', re.IGNORECASE)
JSON_BLOB = re.compile(r'\{[^{}]*"(test_name|results|product|scenario|threads|tps|qps)"[^{}]*\}', re.DOTALL)


def detect_data_source(text: str) -> Dict[str, Optional[str]]:
    """根据用户输入文本判定数据源类型。只支持本地文件和粘贴数据。"""
    if not text:
        return {"type": "keyword_only", "value": None}

    # 1) 本地文件路径
    file_matches = FILE_EXT_PATTERN.findall(text)
    cwd = os.getcwd()
    existing = []
    for fp in file_matches:
        for base in (None, cwd):
            cand = fp if base is None else os.path.join(base, fp)
            if os.path.exists(cand):
                existing.append(os.path.abspath(cand))
                break
    if existing:
        return {
            "type": "local_file",
            "value": existing[0],
            "extras": existing[1:] if len(existing) > 1 else [],
        }

    # 2) 内嵌 JSON 数据（用户直接粘贴）
    json_match = JSON_BLOB.search(text)
    if json_match:
        start = json_match.start()
        depth = 0
        end = start
        for i, ch in enumerate(text[start:], start=start):
            if ch == '{':
                depth += 1
            elif ch == '}':
                depth -= 1
                if depth == 0:
                    end = i + 1
                    break
        blob = text[start:end]
        try:
            json.loads(blob)
            return {"type": "local_data", "value": blob}
        except json.JSONDecodeError:
            pass

    # 3) 默认关键词
    return {"type": "keyword_only", "value": None}


def main():
    import argparse
    ap = argparse.ArgumentParser()
    ap.add_argument('--text', required=True, help='用户输入文本')
    args = ap.parse_args()
    result = detect_data_source(args.text)
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == '__main__':
    main()
#!/usr/bin/env python3
"""
data_source_adapter.py — 统一数据接入（仅支持本地文件和粘贴数据）

适配器：
  - local_file: 本地 .log/.xlsx/.json/.csv
  - local_data: 粘贴的 JSON 文本
  - keyword_only: 仅关键词（将回退为提示用户提供文件）

标准结构：
{
  "meta": {"products": [...], "scenarios": [...], "concurrencies": [...], ...},
  "records": [{"product": ..., "scenario": ..., "threads": ..., "tps": ..., "qps": ..., "p95_ms": ...}, ...]
}
"""
import argparse
import csv
import json
import os
import re
import sys
from collections import defaultdict
from typing import Any, Dict, List, Optional

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from log_parser import parse_log  # noqa: E402


# ============== 反向场景映射 ==============
SCEN_FROM_DB = {
    'point_select': 'oltp_point_select',
    'read_only': 'oltp_read_only',
    'write_only': 'oltp_write_only',
    'read_write': 'oltp_read_write',
    'update_index': 'oltp_update_index',
    'update_non_index': 'oltp_update_non_index',
    'random_points': 'oltp_random_points',
    'random_ranges': 'oltp_random_ranges',
    'tpmC': 'tpmC',
}


def _normalize_scenario(name: str) -> Optional[str]:
    """从 test_name 字符串中识别 sysbench 标准场景名。"""
    if not name:
        return None
    m = re.search(r'(oltp_[a-z_]+)', name, re.IGNORECASE)
    if m:
        return m.group(1).lower()
    for short, full in SCEN_FROM_DB.items():
        if short in name:
            return full
    return None


def _extract_threads(test_name: str, results_key: str) -> Optional[int]:
    m = re.search(r'(\d+)\s*threads?', test_name or '', re.IGNORECASE)
    if m:
        return int(m.group(1))
    m = re.search(r'threads\s*=\s*(\d+)', results_key or '', re.IGNORECASE)
    if m:
        return int(m.group(1))
    return None


# ============== 适配器：本地 log ==============
def adapter_local_log(path: str) -> Dict[str, Any]:
    header, records_raw = parse_log(path)
    product = header.get('engine', os.path.basename(path).split('.')[0])
    records = []
    for r in records_raw:
        scenario = r['scenario']
        if not scenario.startswith('oltp_'):
            scenario = 'oltp_' + scenario.replace('oltp_', '').lstrip('_')
        records.append({
            'product': product,
            'scenario': scenario,
            'threads': r['threads'],
            'tps': r['tps'],
            'qps': r['qps'],
            'p95_ms': r.get('p95_ms'),
            'p99_ms': r.get('p99_ms'),
            'source_log': os.path.basename(path),
        })

    if not records:
        raise RuntimeError(f'日志文件未解析到有效数据: {path}')

    return {
        'meta': {
            'products': [product],
            'scenarios': sorted({r['scenario'] for r in records}),
            'concurrencies': sorted({r['threads'] for r in records}),
            'test_env': {},
            'log_meta': [{
                'product': product,
                'log_file': os.path.basename(path),
                'engine': header['engine'],
                'start_time': header['start_time'],
                'db_endpoint': header['db_endpoint'],
                'data_config': header['data_config'],
                'duration_sec': header['duration_sec'],
            }],
            'source_info': {'type': 'local_file', 'value': path, 'rows_fetched': len(records)},
        },
        'records': records,
    }


# ============== 适配器：本地 xlsx ==============
def adapter_local_xlsx(path: str) -> Dict[str, Any]:
    import openpyxl
    wb = openpyxl.load_workbook(path, data_only=True)
    product_sheets = [s for s in wb.sheetnames if not s.startswith('_')]
    expected = ['scenario', 'threads', 'tps', 'qps', 'p95_ms', 'p99_ms']
    records = []
    products = []
    for sn in product_sheets:
        ws = wb[sn]
        header = [c.value for c in ws[1]]
        if header[:6] != expected:
            raise RuntimeError(f'{sn} 表头不符合标准: {header}')
        products.append(sn)
        for row in ws.iter_rows(min_row=2, values_only=True):
            if not row or row[0] is None:
                continue
            records.append({
                'product': sn,
                'scenario': row[0],
                'threads': row[1],
                'tps': row[2],
                'qps': row[3],
                'p95_ms': row[4],
                'p99_ms': row[5] if len(row) > 5 else None,
                'source_log': os.path.basename(path),
            })
    return {
        'meta': {
            'products': products,
            'scenarios': sorted({r['scenario'] for r in records}),
            'concurrencies': sorted({r['threads'] for r in records}),
            'test_env': {},
            'log_meta': [{'product': p, 'log_file': os.path.basename(path)} for p in products],
            'source_info': {'type': 'local_file', 'value': path, 'rows_fetched': len(records)},
        },
        'records': records,
    }


# ============== 适配器：本地 json ==============
def adapter_local_json(path: str) -> Dict[str, Any]:
    with open(path, encoding='utf-8') as f:
        data = json.load(f)
    if isinstance(data, dict) and 'records' in data and 'meta' in data:
        return data  # 已是标准格式
    if isinstance(data, list):
        # 列表格式：适配为 records
        return adapter_local_rows(data, source_value=path)
    raise RuntimeError(f'JSON 格式不识别: {path}')


# ============== 适配器：本地 csv ==============
def adapter_local_csv(path: str) -> Dict[str, Any]:
    records = []
    with open(path, encoding='utf-8-sig') as f:
        reader = csv.DictReader(f)
        for row in reader:
            records.append({
                'product': row.get('product', os.path.basename(path)),
                'scenario': row['scenario'],
                'threads': int(row['threads']),
                'tps': float(row['tps']),
                'qps': float(row['qps']),
                'p95_ms': float(row['p95_ms']) if row.get('p95_ms') else None,
                'p99_ms': float(row['p99_ms']) if row.get('p99_ms') else None,
            })
    return {
        'meta': {
            'products': sorted({r['product'] for r in records}),
            'scenarios': sorted({r['scenario'] for r in records}),
            'concurrencies': sorted({r['threads'] for r in records}),
            'test_env': {},
            'log_meta': [],
            'source_info': {'type': 'local_file', 'value': path, 'rows_fetched': len(records)},
        },
        'records': records,
    }


# ============== 适配器：本地 JSON 列表数据 ==============
def adapter_local_rows(rows: List[Dict[str, Any]], source_value: str = '') -> Dict[str, Any]:
    """将通用 JSON 行列表转换为标准 records 结构。"""
    records = []
    for row in rows:
        scenario = row.get('scenario', '') or row.get('test_name', '')
        if not scenario or not scenario.startswith('oltp_'):
            # 尝试从 test_name 中提取
            dim = row.get('dimension', {})
            if isinstance(dim, str):
                try:
                    dim = json.loads(dim)
                except Exception:
                    dim = {}
            test_name = dim.get('test_name', '') or row.get('test_name', '')
            scenario = _normalize_scenario(test_name) or scenario

        threads = row.get('threads') or _extract_threads(
            row.get('test_name', '') or (row.get('dimension', {}).get('test_name', '')
                                         if isinstance(row.get('dimension', {}), dict) else ''),
            row.get('results_key', ''),
        )

        tps = _to_float(row.get('tps') or row.get('TPS'))
        qps = _to_float(row.get('qps') or row.get('QPS'))
        results = row.get('results', {})
        if isinstance(results, str):
            try:
                results = json.loads(results)
            except Exception:
                results = {}
        p95 = _to_float(row.get('p95_ms') or results.get('p95') or results.get('p95_latency'))
        p99 = _to_float(row.get('p99_ms') or results.get('p99') or results.get('p99_latency'))

        if not scenario or threads is None:
            continue
        if tps is None and qps is None:
            continue
        qps = qps or tps
        tps = tps or qps

        product = row.get('product', source_value or 'test-product')
        records.append({
            'product': product,
            'scenario': scenario,
            'threads': threads,
            'tps': tps,
            'qps': qps,
            'p95_ms': p95,
            'p99_ms': p99,
        })

    if not records:
        raise RuntimeError(f'未能从数据中解析出有效记录: {source_value}')

    return {
        'meta': {
            'products': sorted({r['product'] for r in records}),
            'scenarios': sorted({r['scenario'] for r in records}),
            'concurrencies': sorted({r['threads'] for r in records}),
            'test_env': {},
            'log_meta': [],
            'source_info': {'type': 'local_data', 'value': source_value, 'rows_fetched': len(records)},
        },
        'records': records,
    }


def _to_float(v):
    if v is None:
        return None
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


# ============== 主分发 ==============
def load_records(intent: Dict[str, Any]) -> Dict[str, Any]:
    ds_type = intent['data_source_type']
    ds_value = intent.get('data_source_value')

    if ds_type == 'local_file':
        if not ds_value or not os.path.exists(ds_value):
            raise RuntimeError(f'本地文件不存在: {ds_value}')
        ext = ds_value.rsplit('.', 1)[-1].lower()
        if ext == 'log':
            return adapter_local_log(ds_value)
        if ext in ('xlsx', 'xls'):
            return adapter_local_xlsx(ds_value)
        if ext == 'json':
            return adapter_local_json(ds_value)
        if ext == 'csv':
            return adapter_local_csv(ds_value)
        raise RuntimeError(f'不识别的扩展名: {ext}')

    if ds_type == 'local_data':
        data = json.loads(ds_value)
        rows = data if isinstance(data, list) else [data]
        return adapter_local_rows(rows, source_value='local_data')

    if ds_type == 'keyword_only':
        raise RuntimeError(
            '未检测到具体的数据文件。'
            '请提供以下格式之一：\n'
            '  - sysbench .log 日志文件路径\n'
            '  - .xlsx Excel 文件路径\n'
            '  - .json 数据文件路径\n'
            '  - .csv 数据文件路径\n'
            '  - 直接粘贴 JSON 数据'
        )

    raise RuntimeError(f'未知 data_source_type: {ds_type}')


# ============== 数据质量门控 ==============
def quality_check(extracted: Dict[str, Any]) -> Dict[str, Any]:
    records = extracted['records']
    n = len(records)
    if n == 0:
        raise RuntimeError('records 为空')

    null_tps = sum(1 for r in records if r.get('tps') is None)
    null_qps = sum(1 for r in records if r.get('qps') is None)
    null_p95 = sum(1 for r in records if r.get('p95_ms') is None)
    null_p99 = sum(1 for r in records if r.get('p99_ms') is None)

    if null_tps or null_qps or null_p95:
        raise RuntimeError(
            f'数据空值率超标 — TPS={null_tps}/{n}, QPS={null_qps}/{n}, P95={null_p95}/{n}'
        )

    cbm = defaultdict(lambda: defaultdict(set))
    for r in records:
        cbm[r['product']][r['scenario']].add(r['threads'])

    return {
        'records': n,
        'tps_null_rate': null_tps / n,
        'qps_null_rate': null_qps / n,
        'p95_null_rate': null_p95 / n,
        'p99_null_rate': null_p99 / n,
        'concurrencies_by_product_scenario': {
            p: {s: sorted(ts) for s, ts in sd.items()} for p, sd in cbm.items()
        },
    }


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--intent', required=True)
    ap.add_argument('--out', required=True)
    args = ap.parse_args()

    with open(args.intent, encoding='utf-8') as f:
        intent = json.load(f)

    extracted = load_records(intent)
    qc = quality_check(extracted)
    extracted['meta']['concurrencies_by_product_scenario'] = qc['concurrencies_by_product_scenario']

    os.makedirs(os.path.dirname(args.out) or '.', exist_ok=True)
    with open(args.out, 'w', encoding='utf-8') as f:
        json.dump(extracted, f, ensure_ascii=False, indent=2, default=str)
    print(f'extracted_data.json 已保存: {args.out}（{qc["records"]} 条记录）')
    print(f'   产品: {extracted["meta"]["products"]}')
    print(f'   场景: {extracted["meta"]["scenarios"][:10]}{"..." if len(extracted["meta"]["scenarios"])>10 else ""}')
    print(f'   并发档: {extracted["meta"]["concurrencies"]}')


if __name__ == '__main__':
    main()
#!/usr/bin/env python3
"""
analyze_core.py — 自包含分析逻辑，不依赖上游 skill。

提供：
  - analyze(): 主分析入口，返回 analysis_results + insights
  - peak_for(): 查找某产品某场景的峰值 QPS 记录
  - scenario_records(): 获取某产品某场景的所有记录
"""
from collections import defaultdict
from typing import Any, Dict, List, Optional, Tuple


def scenario_records(records: List[Dict], product: str, scenario: str) -> List[Dict]:
    """获取某产品某场景的所有记录，按 threads 排序。"""
    return sorted(
        [r for r in records if r['product'] == product and r['scenario'] == scenario],
        key=lambda r: r['threads'],
    )


def peak_for(records: List[Dict], product: str, scenario: str) -> Optional[Dict]:
    """查找某产品某场景的峰值 QPS 记录（含对应 threads 和 p95_ms）。"""
    srs = [r for r in records if r['product'] == product and r['scenario'] == scenario]
    if not srs:
        return None
    peak = max(srs, key=lambda r: r.get('qps', 0))
    return {
        'scenario': scenario,
        'peak_qps': peak['qps'],
        'peak_tps': peak.get('tps'),
        'peak_threads': peak['threads'],
        'peak_p95_ms': peak.get('p95_ms'),
    }


def _single_product_analysis(records: List[Dict], meta: Dict) -> Dict:
    """单产品分析：峰值汇总 + 并发扩展性。"""
    products = meta.get('products', [])
    scenarios = meta.get('scenarios', [])

    single = {}
    for p in products:
        peak_summary = []
        scalability = {}
        for s in scenarios:
            peak = peak_for(records, p, s)
            if peak:
                peak_summary.append(peak)

            srs = scenario_records(records, p, s)
            if srs:
                scalability[s] = {
                    'threads': [r['threads'] for r in srs],
                    'qps': [r['qps'] for r in srs],
                    'tps': [r.get('tps') for r in srs],
                    'p95_ms': [r.get('p95_ms') for r in srs],
                    'p99_ms': [r.get('p99_ms') for r in srs],
                }

        single[p] = {
            'peak_summary': peak_summary,
            'scalability': scalability,
        }

    return single


def _product_compare_analysis(records: List[Dict], meta: Dict) -> Dict:
    """多产品对比分析。"""
    products = meta.get('products', [])
    scenarios = meta.get('scenarios', [])

    # 公平性检查
    fairness = _check_fairness(records, meta)

    compare = {}
    for p in products:
        peak_summary = []
        for s in scenarios:
            peak = peak_for(records, p, s)
            if peak:
                peak_summary.append(peak)
        compare[p] = {'peak_summary': peak_summary}

    # 性能比值矩阵（以第一个产品为 baseline）
    baseline = products[0] if products else None
    ratio_matrix = {}
    if baseline and len(products) >= 2:
        for s in scenarios:
            base_peak = peak_for(records, baseline, s)
            if not base_peak:
                continue
            base_qps = base_peak['peak_qps']
            if not base_qps:
                continue
            row = {baseline: 1.0}
            for p in products[1:]:
                peak = peak_for(records, p, s)
                if peak and peak['peak_qps']:
                    row[p] = peak['peak_qps'] / base_qps
            ratio_matrix[s] = row

    return {
        'products': products,
        'scenarios': scenarios,
        'single_product': compare,
        'ratio_matrix': ratio_matrix,
        'fairness': fairness,
    }


def _check_fairness(records: List[Dict], meta: Dict) -> Dict:
    """公平性检查：并发档、场景覆盖是否一致。"""
    products = meta.get('products', [])
    if len(products) < 2:
        return {'passed': True, 'issues': []}

    issues = []

    # 检查并发档
    conc_by_product = {}
    for p in products:
        threads = sorted({r['threads'] for r in records if r['product'] == p})
        conc_by_product[p] = threads

    ref = conc_by_product[products[0]]
    for p in products[1:]:
        if conc_by_product[p] != ref:
            issues.append(f'并发档不一致：{products[0]}={ref} vs {p}={conc_by_product[p]}')

    # 检查场景覆盖
    scen_by_product = {}
    for p in products:
        scenarios = sorted({r['scenario'] for r in records if r['product'] == p})
        scen_by_product[p] = scenarios

    ref_scen = scen_by_product[products[0]]
    for p in products[1:]:
        if scen_by_product[p] != ref_scen:
            issues.append(f'场景覆盖不一致：{products[0]}={ref_scen} vs {p}={scen_by_product[p]}')

    return {
        'passed': len(issues) == 0,
        'issues': issues,
        'concurrencies': conc_by_product,
        'scenarios': scen_by_product,
    }


def _generate_insights(analysis: Dict, report_type: str) -> List[Dict]:
    """从分析结果生成分级洞察（L1/L2）。"""
    insights: List[Dict] = []
    single = analysis.get('single_product', {})

    for product, data in single.items():
        peak_summary = data.get('peak_summary', [])
        if not peak_summary:
            continue

        # L1: 峰值 QPS 最高/最低场景
        max_ps = max(peak_summary, key=lambda x: x['peak_qps'])
        min_ps = min(peak_summary, key=lambda x: x['peak_qps'])
        insights.append({
            'level': 'L1',
            'text': f'{product} 峰值 QPS 最高出现在 {max_ps["scenario"]}（{max_ps["peak_qps"]:,.0f} @ {max_ps["peak_threads"]} 并发）',
            'source': f'single_product.{product}.peak_summary',
            'scenario': max_ps['scenario'],
        })
        insights.append({
            'level': 'L1',
            'text': f'{product} 峰值 QPS 最低出现在 {min_ps["scenario"]}（{min_ps["peak_qps"]:,.0f} @ {min_ps["peak_threads"]} 并发）',
            'source': f'single_product.{product}.peak_summary',
            'scenario': min_ps['scenario'],
        })

        # L1: 并发扩展性
        scalability = data.get('scalability', {})
        for s, sc in scalability.items():
            if len(sc['qps']) >= 2:
                growth = (sc['qps'][-1] - sc['qps'][0]) / sc['qps'][0] * 100
                insights.append({
                    'level': 'L1',
                    'text': f'{s} 并发扩展率 {growth:+.1f}%（{sc["threads"][0]}→{sc["threads"][-1]} threads）',
                    'source': f'single_product.{product}.scalability.{s}',
                    'scenario': s,
                })

    # 对比报告额外洞察
    if report_type == 'comparison' and 'ratio_matrix' in analysis:
        ratio = analysis['ratio_matrix']
        for s, row in ratio.items():
            products = list(row.keys())
            if len(products) >= 2:
                winner = max(row, key=row.get)
                loser = min(row, key=row.get)
                if row[winner] > 1.01:
                    insights.append({
                        'level': 'L1',
                        'text': f'{s}：{winner} 比 {loser} 快 {row[winner]-1:.1%}',
                        'source': f'ratio_matrix.{s}',
                        'scenario': s,
                    })

        fairness = analysis.get('fairness', {})
        if not fairness.get('passed'):
            for issue in fairness.get('issues', []):
                insights.append({
                    'level': 'L2',
                    'text': f'⚠️ 公平性警告：{issue}',
                    'source': 'fairness',
                    'scenario': 'all',
                })

    return insights


def analyze(extracted: Dict[str, Any]) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    """
    主分析入口。

    返回 (analysis_results, insights)。
    """
    meta = extracted.get('meta', {})
    records = extracted.get('records', [])

    if not records:
        return {'single_product': {}, 'error': '无数据'}, []

    single = _single_product_analysis(records, meta)
    compare = _product_compare_analysis(records, meta)

    results = {
        'single_product': single,
        'product_compare': compare,
    }

    insights = _generate_insights(results, 'single')

    return results, insights

#!/usr/bin/env python3
"""
render_core.py — 自包含三格式渲染器（md/docx/html），不依赖上游 skill。

提供：
  - render_md(report_data) -> str
  - render_docx(report_data, output_path, charts_abs_dir)
  - render_html(report_data) -> str

report_data 结构：
{
    "cover": {"title": "...", "subtitle": "...", "date": "...", "version": "..."},
    "sections": [
        {
            "id": "ch1", "title": "第1章 ...",
            "blocks": [...],           # 顶层 block
            "subsections": [           # 子节
                {
                    "id": "ch1_1", "title": "1.1 ...",
                    "blocks": [
                        {"type": "paragraph", "text": "..."},
                        {"type": "table", "headers": [...], "rows": [[...], ...]},
                        {"type": "image", "path": "charts/xxx.png", "caption": "..."},
                        {"type": "insight", "level": "L1/L2/L3", "text": "...", "source": "..."},
                        {"type": "bullet", "items": ["...", "..."]},
                    ]
                }
            ]
        }
    ]
}
"""
import os
import re
from datetime import datetime
from typing import Any, Dict, List, Optional

try:
    from docx import Document
    from docx.shared import Inches, Pt, Cm, RGBColor
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.enum.table import WD_TABLE_ALIGNMENT
    from docx.oxml.ns import qn
    HAS_DOCX = True
except ImportError:
    HAS_DOCX = False


# ==============================
# Markdown 渲染
# ==============================

def render_md(report_data: Dict[str, Any]) -> str:
    lines = []
    cover = report_data.get('cover', {})

    # 封面
    lines.append(f"# {cover.get('title', '数据库性能测试报告')}")
    lines.append('')
    if cover.get('subtitle'):
        lines.append(f"> {cover['subtitle']}")
        lines.append('')
    lines.append(f"- **日期**：{cover.get('date', datetime.now().strftime('%Y-%m-%d'))}")
    lines.append(f"- **版本**：{cover.get('version', 'v1.0')}")
    lines.append('')
    lines.append('---')
    lines.append('')

    # 目录
    lines.append('## 目录')
    lines.append('')
    for sec in report_data.get('sections', []):
        lines.append(f"- [{sec['title']}](#{_md_anchor(sec['title'])})")
        for sub in sec.get('subsections', []):
            lines.append(f"  - [{sub['title']}](#{_md_anchor(sub['title'])})")
    lines.append('')
    lines.append('---')
    lines.append('')

    # 各章节
    for sec in report_data.get('sections', []):
        lines.append(f"## {sec['title']}")
        lines.append('')

        # 顶层 blocks
        _render_md_blocks(sec.get('blocks', []), lines)

        # 子节
        for sub in sec.get('subsections', []):
            lines.append(f"### {sub['title']}")
            lines.append('')
            _render_md_blocks(sub.get('blocks', []), lines)

    return '\n'.join(lines)


def _render_md_blocks(blocks: List[Dict], lines: List[str]):
    for b in blocks:
        typ = b.get('type', 'paragraph')
        if typ == 'paragraph':
            lines.append(b.get('text', ''))
            lines.append('')
        elif typ == 'table':
            headers = b.get('headers', [])
            rows = b.get('rows', [])
            # 表头
            lines.append('| ' + ' | '.join(str(h) for h in headers) + ' |')
            lines.append('| ' + ' | '.join('---' for _ in headers) + ' |')
            for row in rows:
                lines.append('| ' + ' | '.join(str(c) for c in row) + ' |')
            lines.append('')
        elif typ == 'image':
            caption = b.get('caption', '')
            path = b.get('path', '')
            lines.append(f'![{caption}]({path})')
            if caption:
                lines.append(f'*{caption}*')
            lines.append('')
        elif typ == 'insight':
            level = b.get('level', '')
            text = b.get('text', '')
            lines.append(f'> **[{level}]** {text}')
            lines.append('')
        elif typ == 'bullet':
            for item in b.get('items', []):
                lines.append(f'- {item}')
            lines.append('')


def _md_anchor(title: str) -> str:
    return re.sub(r'[^a-zA-Z0-9\u4e00-\u9fff-]', '', title.lower().replace(' ', '-'))


